const res = $input.first().json;
const fixtures = res.response || [];
const teamFilter = ($env.TEAM_IDS || '').split(',').map(s => s.trim()).filter(Boolean);

const filtered = fixtures.filter(f => {
  if (!teamFilter.length) return true;
  const home = String(f.teams?.home?.id ?? '');
  const away = String(f.teams?.away?.id ?? '');
  return teamFilter.includes(home) || teamFilter.includes(away);
});

if (!filtered.length) {
  return [{ json: { skip: true, reason: 'no_live_fixtures' } }];
}

return filtered.map(f => ({
  json: {
    skip: false,
    fixture: f,
    season: f.league?.season || $env.SEASON_YEAR || '2026',
    leagueLogo: f.league?.logo || ''
  }
}));

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenGoalKeys) staticData.seenGoalKeys = {};

const outputs = [];

for (const item of $input.all()) {
  const fixtureBlock = item.json.fixture || {};
  const fixture = fixtureBlock.fixture || {};
  const teams = fixtureBlock.teams || {};
  const events = Array.isArray(item.json.response) ? item.json.response : [];
  const season = item.json.season || fixtureBlock.league?.season || $env.SEASON_YEAR || '2026';
  const leagueLogo = item.json.leagueLogo || fixtureBlock.league?.logo || '';
  const fixtureId = fixture.id;

  if (!fixtureId) continue;

  const home = teams.home?.name || 'Local';
  const away = teams.away?.name || 'Visitante';
  const scoreHome = fixture.goals?.home ?? '?';
  const scoreAway = fixture.goals?.away ?? '?';
  const homeLogo = teams.home?.logo || '';
  const awayLogo = teams.away?.logo || '';

  for (const ev of events) {
    if (ev.type !== 'Goal') continue;

    const minute = ev.time?.elapsed ?? 0;
    const extra = ev.time?.extra ? `+${ev.time.extra}` : '';
    const player = ev.player?.name || 'Gol';
    const playerId = ev.player?.id || null;
    const teamId = ev.team?.id;
    const teamName = ev.team?.name || '';
    const detail = ev.detail || '';

    const teamLogo = teamId === teams.home?.id ? homeLogo : (teamId === teams.away?.id ? awayLogo : homeLogo);

    const key = `${fixtureId}-${minute}-${playerId || player}-${detail}`;
    if (staticData.seenGoalKeys[key]) continue;
    staticData.seenGoalKeys[key] = Date.now();

    const caption = [
      `⚽ ¡GOL! ${minute}'${extra}`,
      `${home} ${scoreHome} - ${scoreAway} ${away}`,
      `👤 ${player}${teamName ? ` (${teamName})` : ''}`,
      detail ? `📋 ${detail}` : '',
      '',
      $env.IG_HASHTAGS || '#Mundial #Fútbol'
    ].filter(Boolean).join('\n');

    outputs.push({
      json: {
        postType: 'goal',
        skip: false,
        caption,
        playerId,
        season,
        image_url: teamLogo || leagueLogo,
        meta: { home, away, minute, player, teamName, scoreHome, scoreAway, teamLogo, leagueLogo }
      }
    });
  }
}

return outputs.length ? outputs : [{ json: { skip: true, reason: 'no_new_goals' } }];

const prev = $('Detectar gol nuevo').item.json;
const api = $input.first().json;
const playerPhoto = api.response?.[0]?.player?.photo || '';

const image_url = playerPhoto || prev.image_url || prev.meta?.teamLogo || prev.meta?.leagueLogo;

if (!image_url) {
  throw new Error('No se encontró imagen pública para el gol');
}

return [{ json: { ...prev, image_url, imageSource: playerPhoto ? 'player_photo' : 'team_logo' } }];

const prev = $input.first().json;
if (!prev.image_url) {
  throw new Error('No hay escudo de equipo para el gol');
}
return [{ json: { ...prev, imageSource: 'team_logo_only' } }];

const teamFilter = ($env.TEAM_IDS || '').split(',').map(s => s.trim()).filter(Boolean);
if (!teamFilter.length) {
  return [{ json: { skip: true, reason: 'define_TEAM_IDS' } }];
}
return teamFilter.map(id => ({ json: { teamId: id, skip: false } }));

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenTransfers) staticData.seenTransfers = {};

const outputs = [];
const comarca = $env.COMARCA_NAME || 'La comarca';

for (const item of $input.all()) {
  const list = item.json.response || [];
  for (const block of list) {
    const player = block.player;
    const transfers = block.transfers || [];
    const latest = transfers[0];
    if (!latest || !player) continue;

    const key = `${player.id}-${latest.date}-${latest.teams?.in?.id}-${latest.teams?.out?.id}`;
    if (staticData.seenTransfers[key]) continue;

    const daysAgo = (Date.now() - new Date(latest.date).getTime()) / 86400000;
    if (daysAgo > 14) continue;

    staticData.seenTransfers[key] = Date.now();

    const playerName = player.name || 'Jugador';
    const fromClub = latest.teams?.out?.name || '';
    const toClub = latest.teams?.in?.name || '';
    const fee = latest.type || '';

    const caption = [
      `🔄 FICHAJE | ${comarca}`,
      `👤 ${playerName}`,
      fromClub && toClub ? `${fromClub} → ${toClub}` : (toClub || fromClub),
      fee ? `📋 ${fee}` : '',
      '',
      $env.IG_HASHTAGS_TRANSFER || $env.IG_HASHTAGS || '#Fichajes'
    ].filter(Boolean).join('\n');

    outputs.push({
      json: {
        postType: 'transfer',
        skip: false,
        caption,
        playerId: player.id,
        playerName,
        image_url: player.photo || latest.teams?.in?.logo || latest.teams?.out?.logo || '',
        meta: { fromClub, toClub, fee, date: latest.date }
      }
    });
  }
}

return outputs.length ? outputs : [{ json: { skip: true, reason: 'no_new_transfers' } }];

const body = $input.first().json.body || $input.first().json;
const secret = $env.WEBHOOK_SECRET;
if (secret && body.token !== secret) throw new Error('Webhook token inválido');

const playerName = body.player || body.jugador;
if (!playerName) throw new Error('Falta player/jugador');

const fromClub = body.from_club || body.club_origen || '';
const toClub = body.to_club || body.club_destino || '';
const fee = body.fee || body.cantidad || '';
const comarca = body.comarca || $env.COMARCA_NAME || 'La comarca';
const link = body.url || body.link || '';

const caption = [
  `🔄 FICHAJE | ${comarca}`,
  `👤 ${playerName}`,
  fromClub && toClub ? `${fromClub} → ${toClub}` : (toClub || fromClub),
  fee ? `💰 ${fee}` : '',
  link ? `🔗 ${link}` : '',
  '',
  $env.IG_HASHTAGS_TRANSFER || $env.IG_HASHTAGS || '#Fichajes'
].filter(Boolean).join('\n');

return [{
  json: {
    postType: 'transfer',
    skip: false,
    caption,
    playerName,
    playerId: body.player_id || null,
    season: $env.SEASON_YEAR || '2026',
    image_url: body.image_url || body.foto || ''
  }
}];

const prev = $('Preparar fichaje webhook').item.json;
const api = $input.first().json;
const hit = api.response?.[0]?.player;
const image_url = hit?.photo || prev.image_url;
if (!image_url) throw new Error('No se encontró foto del jugador en API-Football');
return [{ json: { ...prev, image_url, playerId: hit?.id || prev.playerId, imageSource: 'player_search' } }];
